const MediaCard_data = [
    { alt: "Self-awareness", imgSrc: "/assets/cloned/svg/f17e1670ac01.svg", srcSet: "/assets/cloned/svg/e1edc05eb1ba.svg 1x, /assets/cloned/svg/f17e1670ac01.svg 2x", title: "Self-awareness", description: "You cannot develop your strengths and work on your weaknesses if you don’t know what they are. The DISC profile test improves your self-awareness, or the ability to objectively and realistically evaluate yourself, which is the foundation of success at work and in life." },
    { alt: "Communication", imgSrc: "/assets/cloned/svg/27a0cf2d88eb.svg", srcSet: "/assets/cloned/svg/f5b79a335e9a.svg 1x, /assets/cloned/svg/27a0cf2d88eb.svg 2x", title: "Communication", description: "If self-awareness is the foundation of personal success, communication is the foundation of great teams. The ability to identify challenges, communicate them effectively and find solutions that work for everyone involved is vital to successful teamwork – and therefore to your organization." },
    { alt: "Conflict resolution", imgSrc: "/assets/cloned/svg/ef421bdcff52.svg", srcSet: "/assets/cloned/svg/87af67617bc9.svg 1x, /assets/cloned/svg/ef421bdcff52.svg 2x", title: "Conflict resolution", description: "When you know how everyone on your team communicates, you can identify where potential conflicts may occur – and get to the root cause more quickly when they do. The DISC profile test can reveal the deeper personality conflicts that are behind team members not getting along." },
    { alt: "Teamwork", imgSrc: "/assets/cloned/svg/39978b9399a9.svg", srcSet: "/assets/cloned/svg/f345a26f041d.svg 1x, /assets/cloned/svg/39978b9399a9.svg 2x", title: "Teamwork", description: "With improved communication and conflict resolution, you’ll discover overall stronger cohesiveness in your teams. Team members will better understand each other and themselves – as well as understanding how they complement each other’s strengths and weaknesses." },
    { alt: "Leadership", imgSrc: "/assets/cloned/svg/82d84b832fee.svg", srcSet: "/assets/cloned/svg/88af547118fe.svg 1x, /assets/cloned/svg/82d84b832fee.svg 2x", title: "Leadership", description: "The ability to communicate, build rapport and influence others is crucial to great leadership – but you cannot do any of that if you don’t understand yourself and those around you. Learning the personalities and working styles of your team will help you become the most effective leader you can be." },
    { alt: "Customer service", imgSrc: "/assets/cloned/svg/84c878d49d31.svg", srcSet: "/assets/cloned/svg/faf10ccdef5c.svg 1x, /assets/cloned/svg/84c878d49d31.svg 2x", title: "Customer service", description: "DISC profiles are especially effective for sales and customer service teams, who need to understand and adapt to many different types of personalities. Knowing their own personalities as well as those of their audience helps them make that real, human connection that prospects and customers are seeking." }
];
